//! Golden Surgery — patient portal (generated by AppCraft).
//! LAN-only demo: read-only views + structured requests into portal_requests.
//! No login in v1 — bind 127.0.0.1, never expose to the internet without auth.
//! See docs/LEGAL-SPIKE.md (network chapter) before any real deployment.

use axum::{
    extract::{Form, Query, State},
    http::StatusCode,
    response::Html,
    routing::{get, post},
    Router,
};
use rusqlite::{params, types::Value, Connection};
use std::{collections::HashMap, net::SocketAddr, sync::Arc};

const APP_TITLE: &str = "Golden Surgery";
const DEFAULT_DB: &str = "golden-surgery.dbcraft";
const DEFAULT_PORT: u16 = 11540;

#[derive(Clone)]
struct AppState {
    db_path: String,
}

fn esc(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

fn shell(title: &str, body: String) -> Html<String> {
    Html(format!(
        "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">\
        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\
        <title>{} — {}</title>\
        <style>body{{font-family:system-ui,sans-serif;max-width:880px;margin:2rem auto;padding:0 1rem;color:#111;background:#fff}}\
        .banner{{background:#fff3cd;border:1px solid #d9a400;padding:.6rem 1rem;border-radius:.5rem;margin-bottom:1.2rem}}\
        nav a{{margin-right:1rem}}table{{border-collapse:collapse;width:100%}}td,th{{border:1px solid #999;padding:.3rem .6rem;text-align:left}}\
        label{{display:block;margin:.6rem 0 .2rem}}input,select{{width:100%;padding:.4rem}}button{{margin-top:1rem;padding:.5rem 1.2rem}}</style>\
        </head><body>\
        <div class=\"banner\"><strong>Demo portal — LAN only, no login.</strong> \
        Not for real patient data over networks. See docs/LEGAL-SPIKE.md.</div>\
        <nav><a href=\"/\">Home</a><a href=\"/onboarding\">New patient</a>\
        <a href=\"/appointments\">Appointments</a><a href=\"/requests\">Staff inbox</a></nav>\
        <h1>{}</h1>{}</body></html>",
        esc(APP_TITLE),
        esc(title),
        esc(title),
        body
    ))
}

fn value_to_string(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Real(f) => f.to_string(),
        Value::Text(s) => s.clone(),
        Value::Blob(b) => format!("<{} bytes>", b.len()),
    }
}

fn db_rows(db: &str, sql: &str) -> Result<(Vec<String>, Vec<Vec<String>>), String> {
    let conn = Connection::open(db).map_err(|e| e.to_string())?;
    let mut stmt = conn.prepare(sql).map_err(|e| e.to_string())?;
    let cols: Vec<String> = stmt.column_names().iter().map(|s| s.to_string()).collect();
    let n = cols.len();
    let mut out = Vec::new();
    let mut q = stmt.query([]).map_err(|e| e.to_string())?;
    while let Some(row) = q.next().map_err(|e| e.to_string())? {
        let mut vals = Vec::new();
        for i in 0..n {
            let v: Value = row.get(i).map_err(|e| e.to_string())?;
            vals.push(value_to_string(&v));
        }
        out.push(vals);
    }
    Ok((cols, out))
}

fn table_html(cols: &[String], rows: &[Vec<String>]) -> String {
    let mut h = String::from("<table><tr>");
    for c in cols {
        h.push_str(&format!("<th>{}</th>", esc(c)));
    }
    h.push_str("</tr>");
    for r in rows {
        h.push_str("<tr>");
        for cell in r {
            h.push_str(&format!("<td>{}</td>", esc(cell)));
        }
        h.push_str("</tr>");
    }
    h.push_str("</table>");
    h
}

fn ensure_requests_table(db: &str) {
    if let Ok(conn) = Connection::open(db) {
        let _ = conn.execute(
            "CREATE TABLE IF NOT EXISTS portal_requests (id INTEGER PRIMARY KEY, req_type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at DATETIME DEFAULT CURRENT_TIMESTAMP)",
            [],
        );
    }
}

async fn home(State(state): State<Arc<AppState>>) -> Html<String> {
    let body = format!(
        "<p>Welcome to {} — appointments, onboarding, and treatment plans. \
        This demo portal reads the local practice file <code>{}</code> and takes structured requests for reception.</p>\
        <ul><li><a href=\"/onboarding\">New patient onboarding</a></li>\
        <li><a href=\"/appointments\">Appointments &amp; booking requests</a></li>\
        <li><a href=\"/treatment\">Treatment plans (needs record number)</a></li>\
        <li><a href=\"/requests\">Staff inbox (reception)</a></li></ul>",
        esc(APP_TITLE),
        esc(&state.db_path)
    );
    shell("Home", body)
}

async fn onboarding_form() -> Html<String> {
    shell(
        "New patient onboarding",
        "<form method=\"post\" action=\"/onboarding\">\
        <label>Full name *<input name=\"full_name\" required></label>\
        <label>Date of birth<input type=\"date\" name=\"date_of_birth\"></label>\
        <label>Gender<select name=\"gender\"><option value=\"\"></option><option>Female</option><option>Male</option><option>Other</option></select></label>\
        <label>Phone<input name=\"phone\"></label>\
        <label>Email<input name=\"email\" type=\"email\"></label>\
        <label>Insurance provider<input name=\"insurance_provider\"></label>\
        <label>Allergies<input name=\"allergies\"></label>\
        <label>Emergency contact<input name=\"emergency_contact\"></label>\
        <button type=\"submit\">Send request</button></form>\
        <p>Reception reviews this before creating your record — nothing is filed automatically.</p>"
            .to_string(),
    )
}

async fn onboarding_submit(
    State(state): State<Arc<AppState>>,
    Form(f): Form<HashMap<String, String>>,
) -> Result<Html<String>, (StatusCode, String)> {
    let get = |k: &str| f.get(k).cloned().unwrap_or_default();
    let name = get("full_name").trim().to_string();
    if name.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "Full name is required.".to_string()));
    }
    let payload = serde_json::json!({
        "full_name": name,
        "date_of_birth": get("date_of_birth"),
        "gender": get("gender"),
        "phone": get("phone"),
        "email": get("email"),
        "insurance_provider": get("insurance_provider"),
        "allergies": get("allergies"),
        "emergency_contact": get("emergency_contact"),
    })
    .to_string();
    let conn = Connection::open(&state.db_path).map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    conn.execute(
        "INSERT INTO portal_requests (req_type, payload, status) VALUES ('onboarding', ?1, 'new')",
        params![payload],
    )
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    let id = conn.last_insert_rowid();
    Ok(shell(
        "Request received",
        format!(
            "<p>Thank you, {}. Your reference is <strong>ONB-{}</strong>. The practice will call you back.</p><p><a href=\"/\">Back home</a></p>",
            esc(&name),
            id
        ),
    ))
}

async fn appointments(State(state): State<Arc<AppState>>) -> Html<String> {
    let upcoming = db_rows(
        &state.db_path,
        "SELECT a.id, p.full_name, a.scheduled_time, a.status, a.chief_complaint FROM appointments a JOIN patients p ON p.id = a.patient_id WHERE a.status IN ('scheduled','checked_in','in_consultation') ORDER BY a.scheduled_time LIMIT 100",
    );
    let mut body = String::from("<h2>Upcoming</h2>");
    match upcoming {
        Ok((cols, rows)) => body.push_str(&table_html(&cols, &rows)),
        Err(e) => body.push_str(&format!("<p>{}</p>", esc(&e))),
    }
    body.push_str(
        "<h2>Request a booking</h2>\
        <form method=\"post\" action=\"/appointments/request\">\
        <label>Record number (e.g. PAT-2026-0041)<input name=\"record_number\" required></label>\
        <label>Preferred date/time<input name=\"preferred\"></label>\
        <label>Reason<input name=\"reason\"></label>\
        <button type=\"submit\">Send request</button></form>",
    );
    shell("Appointments", body)
}

async fn appointment_request(
    State(state): State<Arc<AppState>>,
    Form(f): Form<HashMap<String, String>>,
) -> Result<Html<String>, (StatusCode, String)> {
    let get = |k: &str| f.get(k).cloned().unwrap_or_default();
    let rec = get("record_number").trim().to_string();
    if rec.is_empty() {
        return Err((StatusCode::BAD_REQUEST, "Record number is required.".to_string()));
    }
    let conn = Connection::open(&state.db_path).map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    let pid: Result<i64, _> =
        conn.query_row("SELECT id FROM patients WHERE record_number = ?1", params![rec], |r| r.get(0));
    let pid = match pid {
        Ok(id) => id,
        Err(_) => return Ok(shell("Not found", format!("<p>No patient with record number <strong>{}</strong>. Check the number on your card and try again.</p><p><a href=\"/appointments\">Back</a></p>", esc(&rec)))),
    };
    let payload = serde_json::json!({
        "patient_id": pid,
        "record_number": rec,
        "preferred": get("preferred"),
        "reason": get("reason"),
    })
    .to_string();
    conn.execute(
        "INSERT INTO portal_requests (req_type, payload, status) VALUES ('booking', ?1, 'new')",
        params![payload],
    )
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()))?;
    let id = conn.last_insert_rowid();
    Ok(shell(
        "Request received",
        format!(
            "<p>Booking request <strong>BKG-{}</strong> is with reception. They confirm by phone.</p><p><a href=\"/appointments\">Back</a></p>",
            id
        ),
    ))
}

async fn treatment(State(state): State<Arc<AppState>>, Query(q): Query<HashMap<String, String>>) -> Html<String> {
    let empty = String::new();
    let rec = q.get("record").unwrap_or(&empty).trim().to_string();
    if rec.is_empty() {
        return shell(
            "Treatment plans",
            "<form method=\"get\" action=\"/treatment\">\
            <label>Record number (e.g. PAT-2026-0041)<input name=\"record\" required></label>\
            <button type=\"submit\">Show my plan</button></form>"
                .to_string(),
        );
    }
    let conn = match Connection::open(&state.db_path) {
        Ok(c) => c,
        Err(e) => return shell("Error", format!("<p>{}</p>", esc(&e.to_string()))),
    };
    let pat: Result<(String, String), _> = conn.query_row(
        "SELECT full_name, record_number FROM patients WHERE record_number = ?1",
        params![rec],
        |r| Ok((r.get(0)?, r.get(1)?)),
    );
    let (pname, pnr): (String, String) = match pat {
        Ok(v) => v,
        Err(_) => {
            return shell(
                "Not found",
                format!("<p>No patient with record number <strong>{}</strong>.</p>", esc(&rec)),
            )
        }
    };
    let mut body = format!("<h2>{} ({})</h2>", esc(&pname), esc(&pnr));
    for (title, sql) in [
        ("Appointments", format!("SELECT scheduled_time, status, chief_complaint FROM appointments WHERE patient_id = (SELECT id FROM patients WHERE record_number = '{}') ORDER BY scheduled_time", rec.replace('\'', ""))),
        ("Clinical notes", format!("SELECT created_at, subjective_notes, assessment, plan_treatment FROM clinical_notes WHERE patient_id = (SELECT id FROM patients WHERE record_number = '{}') ORDER BY created_at DESC LIMIT 50", rec.replace('\'', ""))),
        ("Prescriptions", format!("SELECT medication_name, dosage, frequency, issued_date FROM prescriptions WHERE patient_id = (SELECT id FROM patients WHERE record_number = '{}') ORDER BY issued_date DESC", rec.replace('\'', ""))),
    ] {
        body.push_str(&format!("<h3>{}</h3>", title));
        match db_rows(&state.db_path, &sql) {
            Ok((cols, rows)) if !rows.is_empty() => body.push_str(&table_html(&cols, &rows)),
            Ok(_) => body.push_str("<p>Nothing on file.</p>"),
            Err(e) => body.push_str(&format!("<p>{}</p>", esc(&e))),
        }
    }
    shell("Treatment plan", body)
}

async fn requests(State(state): State<Arc<AppState>>) -> Html<String> {
    let mut body = String::from("<h2>Reception inbox (newest first)</h2>");
    match db_rows(
        &state.db_path,
        "SELECT id, req_type, status, created_at, substr(payload, 1, 220) FROM portal_requests ORDER BY id DESC LIMIT 100",
    ) {
        Ok((cols, rows)) => body.push_str(&table_html(&cols, &rows)),
        Err(e) => body.push_str(&format!("<p>{}</p>", esc(&e))),
    }
    shell("Staff inbox", body)
}

#[tokio::main]
async fn main() {
    let mut db = DEFAULT_DB.to_string();
    let mut port = DEFAULT_PORT;
    let mut bind = "127.0.0.1".to_string();
    let mut it = std::env::args().skip(1);
    while let Some(a) = it.next() {
        if a == "--db" {
            if let Some(v) = it.next() {
                db = v;
            }
        } else if a == "--port" {
            if let Some(v) = it.next() {
                if let Ok(p) = v.parse::<u16>() {
                    port = p;
                }
            }
        } else if a == "--bind" {
            if let Some(v) = it.next() {
                bind = v;
            }
        }
    }
    ensure_requests_table(&db);
    let state = Arc::new(AppState { db_path: db });
    let app = Router::new()
        .route("/", get(home))
        .route("/onboarding", get(onboarding_form).post(onboarding_submit))
        .route("/appointments", get(appointments))
        .route("/appointments/request", post(appointment_request))
        .route("/treatment", get(treatment))
        .route("/requests", get(requests))
        .with_state(state);
    let addr: SocketAddr = format!("{bind}:{port}")
        .parse()
        .unwrap_or(SocketAddr::from(([127, 0, 0, 1], DEFAULT_PORT)));
    println!("{APP_TITLE} portal on http://{addr} (LAN demo, no login — see LEGAL-SPIKE.md)");
    let listener = tokio::net::TcpListener::bind(addr).await.unwrap_or_else(|e| {
        eprintln!("bind failed: {e}");
        std::process::exit(1);
    });
    if let Err(e) = axum::serve(listener, app).await {
        eprintln!("server error: {e}");
    }
}
